/**
 * Workspace-scoped file access for the Office tools.
 *
 * Reads go through `ctx.fs.readBytes` so the harness sees them as file
 * observations (and a future remote backend still works). Writes cannot go
 * through `ctx.fs.writeText` — that API is UTF-8 text only, and a .docx is
 * binary — so they use `node:fs` with two fences: the destination must
 * canonicalize inside the session workspace, and `read-only` mode refuses the
 * call outright. The write itself is staged to a sibling temp file and
 * renamed, so a failed generation never leaves a half-written document that
 * the next `office_read` would report as corrupt.
 */

import { mkdir, rename, unlink, writeFile } from "node:fs/promises";
import { dirname } from "node:path";

import { OfficeError } from "./errors.js";

/** Resolve a model-supplied path and require it to stay inside the workspace. */
export async function resolveInside(ctx, exec, inputPath) {
	const clean = String(inputPath ?? "").trim();
	if (clean.length === 0) throw new OfficeError("path is required", "OFFICE_BAD_ARGS");
	const cwd = await ctx.workingDirectory.ensure(exec.agent, exec.signal);
	const root = await ctx.fs.resolve(cwd);
	const target = await ctx.fs.resolve(clean, { cwd, signal: exec.signal });
	if (!ctx.fs.contains(root, target)) {
		throw new OfficeError(`path escapes the session workspace: ${clean}`, "OFFICE_SANDBOX_DENIED");
	}
	return { cwd, root, target, path: ctx.fs.processPath(target) };
}

/** Read a workspace file with an explicit byte ceiling. */
export async function readInside(ctx, exec, inputPath, maxBytes) {
	const resolved = await resolveInside(ctx, exec, inputPath);
	const info = await ctx.fs.stat(resolved.target, exec.signal);
	if (info === undefined) throw new OfficeError(`file not found: ${inputPath}`, "OFFICE_NOT_FOUND");
	if (info.type !== "file") throw new OfficeError(`not a regular file: ${inputPath}`, "OFFICE_NOT_FOUND");
	if (info.size !== undefined && info.size > maxBytes) {
		throw new OfficeError(`file is too large to read on device (${info.size} > ${maxBytes} bytes)`, "OFFICE_TOO_LARGE");
	}
	const bytes = await ctx.fs.readBytes(resolved.target, exec.signal, maxBytes);
	return { ...resolved, bytes: Buffer.from(bytes), size: info.size ?? bytes.length };
}

/**
 * Atomically write bytes to a workspace path.
 * `read-only` mode refuses before touching the filesystem; every other mode
 * still requires containment, because the Office tools never need to write
 * outside the project the user opened.
 */
export async function writeInside(ctx, exec, inputPath, bytes) {
	const resolved = await resolveInside(ctx, exec, inputPath);
	if (ctx.fs.sandboxMode === "read-only") {
		throw new OfficeError("the session is in read-only mode; switch permission to write files", "OFFICE_SANDBOX_DENIED");
	}
	const directory = dirname(resolved.path);
	await mkdir(directory, { recursive: true });
	const temp = `${resolved.path}.tmp-${process.pid.toString(36)}-${Date.now().toString(36)}`;
	try {
		await writeFile(temp, bytes, { mode: 0o644 });
		await rename(temp, resolved.path);
	} catch (error) {
		await unlink(temp).catch(() => {});
		throw new OfficeError(`cannot write ${inputPath}: ${error.message}`, "OFFICE_WRITE_FAILED");
	}
	return { ...resolved, bytes: bytes.length };
}
